9	static std::shared_ptr<ncnn_llm_gpt_ctx> create_ctx(int sconv_cnt, int gdr_cnt) {
10	    if (sconv_cnt > 0 || gdr_cnt > 0) {
11	        return std::make_shared<qwen3_5_ctx>();
12	    }
13	    return std::make_shared<ncnn_llm_gpt_base_ctx>();
14	}
