16	// Class Implementation
17	
18	ncnn_llm_gpt::ncnn_llm_gpt(const std::string& model_path, bool use_vulkan, int num_threads, int vulkan_device) 
19	    : vision_type(Vision_Type::VISION_CLOSE) {
20	    try {
21	        json config;
22	        {
23	            std::ifstream ifs(model_path + "/model.json");
24	            ifs >> config;
25	        }
26	        
27	        // Load base model
28	        decoder_net = std::make_shared<ncnn::Net>();
29	        embed_net = std::make_shared<ncnn::Net>();
30	        proj_out_net = std::make_shared<ncnn::Net>();
31	
32	        // Set number of threads (0 = use ncnn default which is get_cpu_count())
33	        if (num_threads > 0) {
34	            decoder_net->opt.num_threads = num_threads;
35	            embed_net->opt.num_threads = num_threads;
36	            proj_out_net->opt.num_threads = num_threads;
37	        }
38	
39	        if (use_vulkan) {
40	            printf("[ncnn_llm_gpt] Vulkan enabled, using device %d\n", vulkan_device >= 0 ? vulkan_device : 0);
41	            // Only decoder_net uses Vulkan for compute-intensive operations
42	
43	            // Set specific Vulkan device BEFORE enabling vulkan compute
44	            if (vulkan_device >= 0) {
45	                decoder_net->opt.vulkan_device_index = vulkan_device;
46	            }
47	            decoder_net->opt.use_bf16_storage = true;
48	            // decoder_net->opt.use_bf16_packed = true;
49	            decoder_net->opt.use_fp16_arithmetic = false;
50	            decoder_net->opt.use_fp16_storage = false;
51	            decoder_net->opt.use_fp16_packed = false;
52	            decoder_net->opt.use_vulkan_compute = true;
53	        } else {
54	            printf("[ncnn_llm_gpt] Vulkan disabled, using CPU only\n");
55	        }
56	
57	
58	        std::string decoder_param = model_path + "/" + config["params"]["decoder_param"].get<std::string>();
59	        std::string decoder_bin = model_path + "/" + config["params"]["decoder_bin"].get<std::string>();
60	        std::string embed_param = model_path + "/" + config["params"]["embed_token_param"].get<std::string>();
61	        std::string embed_bin = model_path + "/" + config["params"]["embed_token_bin"].get<std::string>();
62	        std::string proj_out_param = model_path + "/" + config["params"]["proj_out_param"].get<std::string>();
63	        std::string proj_out_bin = model_path + "/" + config["params"]["proj_out_bin"].get<std::string>();
64	
65	        printf("Loading model from %s\n", model_path.c_str());
66	        printf("  decoder param: %s\n", decoder_param.c_str());
67	        printf("  decoder bin: %s\n", decoder_bin.c_str());
68	        printf("  embed param: %s\n", embed_param.c_str());
69	        printf("  embed bin: %s\n", embed_bin.c_str());
70	        printf("  proj_out param: %s\n", proj_out_param.c_str());
71	        printf("  proj_out bin: %s\n", proj_out_bin.c_str());
72	
73	        register_gdr_layers(*decoder_net);
74	
75	        decoder_net->load_param(decoder_param.c_str());
76	        decoder_net->load_model(decoder_bin.c_str());
77	        embed_net->load_param(embed_param.c_str());
78	        embed_net->load_model(embed_bin.c_str());
79	        proj_out_net->load_param(proj_out_param.c_str());
80	        proj_out_net->load_model(proj_out_bin.c_str());
81	
82	        // Load tokenizer
83	        std::string type = "bpe";
84	        if (config["tokenizer"].contains("type")) {
85	            type = config["tokenizer"]["type"].get<std::string>();
86	        }
87	        std::string vocab_file = model_path + "/" + config["tokenizer"]["vocab_file"].get<std::string>();
88	        std::string merges_file = model_path + "/" + config["tokenizer"]["merges_file"].get<std::string>();
89	
90	        bpe = std::make_shared<BpeTokenizer>(BpeTokenizer::LoadFromFiles(
91	            vocab_file, merges_file, SpecialTokensConfig{}, false, true, type == "bbpe"
92	        ));
93	
94	        std::vector<std::string> additional_special_tokens = config["tokenizer"]["additional_special_tokens"].get<std::vector<std::string>>();
95	        for (const auto& token : additional_special_tokens) {
96	            bpe->AddAdditionalSpecialToken(token);
97	        }
98	
99	        auto eos_token = config["tokenizer"]["eos"].get<std::string>();
100	        eos = (eos_token != "") ? bpe->token_to_id().at(eos_token) : -1;
101	
102	        auto bos_token = config["tokenizer"]["bos"].get<std::string>();
103	        bos = (bos_token != "") ? bpe->token_to_id().at(bos_token) : -1;
104	
105	        // Model settings
106	        if (config["setting"].contains("attn_cnt")) {
107	            attn_cnt = config["setting"]["attn_cnt"].get<int>();
108	        }
109	        if (config["setting"].contains("sconv_cnt")) {
110	            sconv_cnt = config["setting"]["sconv_cnt"].get<int>();
111	        }
112	        if (config["setting"].contains("gdr_cnt")) {
113	            gdr_cnt = config["setting"]["gdr_cnt"].get<int>();
114	        }
115	
116	        if (config["setting"].contains("rope")) {
117	            auto rope_cfg = config["setting"]["rope"];
118	            if (rope_cfg.contains("rope_head_dim")) {
119	                rope_head_dim = rope_cfg["rope_head_dim"].get<int>();
120	            }
121	            if (rope_cfg["type"] == "LongRoPE") {
122	                rope_type = RoPE_Type::LongRoPE;
123	                short_factor = rope_cfg["short_factor"].get<std::vector<float>>();
124	                long_factor = rope_cfg["long_factor"].get<std::vector<float>>();
125	                original_max_position_embeddings = rope_cfg["original_max_position_embeddings"].get<int>();
126	            } else if (rope_cfg["type"] == "RoPE") {
127	                rope_type = RoPE_Type::RoPE;
128	            } else if (rope_cfg["type"] == "NTKRoPE") {
129	                // rope_scaling
130	                rope_type = RoPE_Type::NTK_RoPE;
131	            } else if (rope_cfg["type"] == "YaRNRoPE") {
132	                rope_type = RoPE_Type::YARN_RoPE;
133	            }
134	
135	            if (rope_cfg.contains("rope_scaling"))
136	            {
137	                ntk_scaling_params.alpha = rope_cfg["rope_scaling"]["alpha"].get<float>();
138	                ntk_scaling_params.beta_fast = rope_cfg["rope_scaling"]["beta_fast"].get<float>();
139	                ntk_scaling_params.beta_slow = rope_cfg["rope_scaling"]["beta_slow"].get<float>();
140	                ntk_scaling_params.factor = rope_cfg["rope_scaling"]["factor"].get<float>();
141	                ntk_scaling_params.mscale = rope_cfg["rope_scaling"]["mscale"].get<float>();
142	                ntk_scaling_params.mscale_all_dim = rope_cfg["rope_scaling"]["mscale_all_dim"].get<float>();
143	            }
144	
145	            rope_theta = rope_cfg["rope_theta"].get<float>();
146	        }
147	
148	        if (config["setting"].contains("functions")) {
149	            auto func_cfg = config["setting"]["functions"];
150	            if (func_cfg["type"].get<std::string>() == "tool_call") {
151	                if (func_cfg.contains("tool_call_id")) {
152	                    tool_call_id = bpe->token_to_id().at(func_cfg["tool_call_id"].get<std::string>());
153	                    fprintf(stderr, "  tool_call_id: %d\n", tool_call_id);
154	                }
155	                if (func_cfg.contains("tool_call_end_id")) {
156	                    tool_call_end_id = bpe->token_to_id().at(func_cfg["tool_call_end_id"].get<std::string>());
157	                    fprintf(stderr, "  tool_call_end_id: %d\n", tool_call_end_id);
158	                }
159	            }
160	        }
161	
162	        // Load think tokens if present in tokenizer
163	        auto it_think = bpe->token_to_id().find("<think>");
164	        if (it_think != bpe->token_to_id().end()) {
165	            think_id = it_think->second;
166	            fprintf(stderr, "  think_id: %d\n", think_id);
167	        }
168	        auto it_think_end = bpe->token_to_id().find("</think>");
169	        if (it_think_end != bpe->token_to_id().end()) {
170	            think_end_id = it_think_end->second;
171	            fprintf(stderr, "  think_end_id: %d\n", think_end_id);
172	        }
173	
174	        // Vision settings
175	        std::string vision_type_str = "close";
176	        if (config["setting"].contains("vision")) {
177	            auto vision_cfg = config["setting"]["vision"];
178	            vision_type_str = vision_cfg["type"].get<std::string>();
179	            
180	            if (vision_type_str != "close") {
181	                if (vision_type_str == "vit") {
182	                    vision_type = Vision_Type::VISION_VIT;
183	                } else if (vision_type_str == "qwen3.5_vl") {
184	                    vision_type = Vision_Type::VISION_QWEN3_5_VL;
185	                }
186	                
187	                std::string vision_embed_patch_param = model_path + "/" + vision_cfg["vision_embed_patch_param"].get<std::string>();
188	                std::string vision_embed_patch_bin = model_path + "/" + vision_cfg["vision_embed_patch_bin"].get<std::string>();
189	                std::string vision_encoder_param = model_path + "/" + vision_cfg["vision_encoder_param"].get<std::string>();
190	                std::string vision_encoder_bin = model_path + "/" + vision_cfg["vision_encoder_bin"].get<std::string>();
191	
192	                fprintf(stderr, "  vision embed patch param: %s\n", vision_embed_patch_param.c_str());
193	                fprintf(stderr, "  vision embed patch bin: %s\n", vision_embed_patch_bin.c_str());
194	                fprintf(stderr, "  vision encoder param: %s\n", vision_encoder_param.c_str());
195	                fprintf(stderr, "  vision encoder bin: %s\n", vision_encoder_bin.c_str());
196	
197	                vision_embed_patch = std::make_shared<ncnn::Net>();
198	                vision_encoder = std::make_shared<ncnn::Net>();
199	
200	                if (use_vulkan) {
201	                    vision_embed_patch->opt.use_vulkan_compute = true;
202	                    vision_encoder->opt.use_vulkan_compute = true;
203	                }
204	                vision_embed_patch->load_param(vision_embed_patch_param.c_str());
205	                vision_embed_patch->load_model(vision_embed_patch_bin.c_str());
206	                vision_encoder->load_param(vision_encoder_param.c_str());
207	                vision_encoder->load_model(vision_encoder_bin.c_str());
208	
209	                if (vision_cfg.contains("vision_embed_pos_param")) {
210	                    std::string vision_embed_pos_param = model_path + "/" + vision_cfg["vision_embed_pos_param"].get<std::string>();
211	                    std::string vision_embed_pos_bin = model_path + "/" + vision_cfg["vision_embed_pos_bin"].get<std::string>();
212	                    fprintf(stderr, "  vision embed pos param: %s\n", vision_embed_pos_param.c_str());
213	                    fprintf(stderr, "  vision embed pos bin: %s\n", vision_embed_pos_bin.c_str());
214	                    
215	                    vision_embed_pos = std::make_shared<ncnn::Net>();
216	                    if (use_vulkan) {
217	                        vision_embed_pos->opt.use_vulkan_compute = true;
218	                    }
219	                    vision_embed_pos->load_param(vision_embed_pos_param.c_str());
220	                    vision_embed_pos->load_model(vision_embed_pos_bin.c_str());
221	                }
222	
223	                auto it = bpe->token_to_id().find("<|image_pad|>");
224	                if (it != bpe->token_to_id().end()) {
225	                    image_pad_id = it->second;
226	                }
227	
228	                // Load vision config
229	                patch_size = vision_cfg["patch_size"].get<int>();
230	                patch_dim = vision_cfg["patch_dim"].get<int>();
231	                max_num_patches = vision_cfg["max_num_patches"].get<int>();
232	                spatial_merge_size = vision_cfg["spatial_merge_size"].get<int>();
233	
234	                if (vision_cfg.contains("rope")) {
235	                    auto rope_cfg = vision_cfg["rope"];
236	                    if (rope_cfg["type"] == "mRoPE") {
237	                        vision_rope_type = VisionRoPE_Type::mRoPE;
238	                        mrope_section = rope_cfg["mrope_section"].get<std::vector<int>>();
239	                    }
240	                }
241	            }
242	        }
243	    } catch (std::exception &e) {
244	        throw std::runtime_error(std::string("ncnn_llm_gpt load model failed: ") + e.what());
245	    }
246	}
