438	std::shared_ptr<ncnn_llm_gpt_ctx> ncnn_llm_gpt::prefill(const std::string& input_text, const ncnn::Mat& bgr, const std::shared_ptr<ncnn_llm_gpt_ctx> ctx) const {
439	    std::shared_ptr<ncnn_llm_gpt_ctx> new_ctx = clone_ctx(ctx);
440	
441	    ncnn::Mat image_embeds;
442	    int num_patches_w = 0;
443	    int num_patches_h = 0;
444	    get_visiual_features(bgr, image_embeds, num_patches_w, num_patches_h);
445	
446	    const int image_embeds_size = image_embeds.h;
447	
448	    auto token_ids = bpe->encode(input_text, false, false);
449	    int last_token_id = token_ids.back();
450	    token_ids.pop_back();
451	
452	    ncnn::Mat input_ids_mat = ncnn::Mat((int)token_ids.size(), 1, (void*)token_ids.data()).clone();
453	    ncnn::Mat token_embed;
454	    {
455	        ncnn::Extractor ex = embed_net->create_extractor();
456	        ex.input("in0", input_ids_mat);
457	        ex.extract("out0", token_embed);
458	    }
459	
460	    int image_pad_index = -1;
461	    inject_image_embeds(token_ids, token_embed, image_pad_index, image_pad_id, image_embeds);
462	
463	    ncnn::Mat cos_cache, sin_cache;
464	    if (image_embeds.empty()) {
465	        generate_rope_embed_cache(token_ids.size(), rope_head_dim, new_ctx->position_id, cos_cache, sin_cache, rope_theta);
466	        new_ctx->position_id += token_ids.size();
467	    } else {
468	        if (vision_type == Vision_Type::VISION_QWEN3_5_VL) {
469	            generate_rope_embed_cache_vision_mrope_interleaved(token_ids.size(), rope_head_dim, new_ctx->position_id, image_pad_index, image_embeds_size, num_patches_w, cos_cache, sin_cache, rope_theta);
470	        } else {
471	            generate_rope_embed_cache_vision_mrope(token_ids.size(), rope_head_dim, new_ctx->position_id, image_pad_index, image_embeds_size, num_patches_w, spatial_merge_size, mrope_section, cos_cache, sin_cache, rope_theta);
472	        }
473	        new_ctx->position_id += token_ids.size() - image_embeds_size + (num_patches_w / spatial_merge_size);
474	    }
475	
476	    ncnn::Mat mask((int)token_ids.size() + new_ctx->kv_cache[0].first.h, (int)token_ids.size());
477	    mask.fill(0.0f);
478	    for (int i = 0; i < (int)token_ids.size(); i++) {
479	        float* row = mask.row(i);
480	        for (int j = new_ctx->kv_cache[0].first.h + i + 1; j < (int)token_ids.size() + new_ctx->kv_cache[0].first.h; j++) {
481	            row[j] = -1e38f;
482	        }
483	    }
484	
485	    ncnn::Mat decode_out;
486	    {
487	        ncnn::Extractor ex = decoder_net->create_extractor();
488	        ex.input("in0", token_embed);
489	        ex.input("in1", mask);
490	        ex.input("in2", cos_cache);
491	        ex.input("in3", sin_cache);
492	
493	        for (int i = 0; i < attn_cnt; i++) {
494	            char kname[32], vname[32];
495	            std::snprintf(kname, sizeof(kname), "cache_k%d", i);
496	            std::snprintf(vname, sizeof(vname), "cache_v%d", i);
497	            ex.input(kname, new_ctx->kv_cache[i].first);
498	            ex.input(vname, new_ctx->kv_cache[i].second);
499	        }
500	
501	        auto qwen_ctx = std::dynamic_pointer_cast<qwen3_5_ctx>(new_ctx);
502	        if (qwen_ctx) {
503	            for (int i = 0; i < sconv_cnt; ++i) {
504	                char name[16];
505	                std::snprintf(name, sizeof(name), "cache_conv%d", i);
506	                ex.input(name, qwen_ctx->sconv_cache[i]);
507	            }
508	            for (int i = 0; i < gdr_cnt; ++i) {
