843	std::shared_ptr<ncnn_llm_gpt_ctx> ncnn_llm_gpt::generate(const std::shared_ptr<ncnn_llm_gpt_ctx>& ctx_in, const GenerateConfig& cfg, std::function<void(const std::string&)> callback) const {
844	    const int vocab_size = bpe->vocab_size();
845	
846	    auto handle_tool = [&](const std::string& tool_call_text, std::shared_ptr<ncnn_llm_gpt_ctx>& ctx_ref) {
847	        nlohmann::json tool_call_json;
848	        try {
849	            tool_call_json = nlohmann::json::parse(tool_call_text);
850	        } catch (const std::exception& e) {
851	            tool_call_json = nlohmann::json::object();
852	        }
853	
854	        nlohmann::json tool_resp;
855	        if (cfg.tool_callback) {
856	            tool_resp = cfg.tool_callback(tool_call_json);
857	        } else {
858	            tool_resp = nlohmann::json{{"tool_call", tool_call_json}};
859	        }
860	
861	        std::string tool_response_pre = "<|im_end|>\n<|im_start|>user\n<tool_response>\n\n";
862	        std::string tool_response_post = "\n\n</tool_response><|im_end|>\n<|im_start|>assistant\n<think>\n</think>\n\n";
863	
864	        ctx_ref = prefill(tool_response_pre + tool_resp.dump() + tool_response_post, ctx_ref);
865	    };
866	
867	    auto ctx = clone_ctx(ctx_in);
868	    std::unordered_set<int> history;
869	    history.insert(ctx->cur_token);
870	
871	    bool flag_in_tool_call = false;
872	    std::string tool_call_content;
873	
874	    for (int step = 0; step < cfg.max_new_tokens; ++step) {
875	        if (ctx->cur_token == eos) break;
876	
877	        if (ctx->cur_token == tool_call_id) {
878	            flag_in_tool_call = true;
879	        } else if (ctx->cur_token == tool_call_end_id) {
880	            flag_in_tool_call = false;
881	            handle_tool(tool_call_content, ctx);
882	            tool_call_content.clear();
883	            history.clear();
884	            history.insert(ctx->cur_token);
885	            continue;
886	        } else if (flag_in_tool_call) {
887	            tool_call_content += bpe->decode({ctx->cur_token}, false);
888	        } else {
889	            callback(bpe->decode({ctx->cur_token}, false));
890	        }
891	
892	        ncnn::Mat cur_embed = llm_run_text_embed(*embed_net, ctx->cur_token);
893	
894	        ncnn::Mat cos_cache, sin_cache;
895	        if (rope_type == RoPE_Type::LongRoPE) {
896	            generate_rope_embed_cache_LongRoPE(1, rope_head_dim, ctx->position_id, cos_cache, sin_cache, rope_theta, short_factor.data(), long_factor.data(), original_max_position_embeddings);
897	        } else if (rope_type == RoPE_Type::NTK_RoPE) {
898	            generate_ntk_rope_embed_cache(1, rope_head_dim, ctx->position_id, cos_cache, sin_cache, rope_theta, ntk_scaling_params);
899	        } else if (rope_type == RoPE_Type::YARN_RoPE) {
900	            generate_yarn_rope_embed_cache(1, rope_head_dim, ctx->position_id, cos_cache, sin_cache, rope_theta, ntk_scaling_params);
901	        }
902	        else {
903	            generate_rope_embed_cache(1, rope_head_dim, ctx->position_id, cos_cache, sin_cache, rope_theta);
904	        }
905	        
906	        ctx->position_id++;
907	
908	        ncnn::Mat mask(ctx->kv_cache[0].first.h + 1, 1);
909	        mask.fill(0.f);
910	
911	        ncnn::Mat decode_out;
912	        auto qwen_ctx = std::dynamic_pointer_cast<qwen3_5_ctx>(ctx);
913	        if (!qwen_ctx) {
914	            decode_out = llm_run_decoder_with_kv(*decoder_net, cur_embed, mask, cos_cache, sin_cache,
915	                                                 ctx->kv_cache, attn_cnt, false);
916	        } else {
917	            ncnn::Extractor ex = decoder_net->create_extractor();
918	            ex.input("in0", cur_embed);
919	            ex.input("in1", mask);
920	            ex.input("in2", cos_cache);
921	            ex.input("in3", sin_cache);
922	
923	            for (int i = 0; i < attn_cnt; ++i) {
924	                char kname[16], vname[16];
925	                std::snprintf(kname, sizeof(kname), "cache_k%d", i);
926	                std::snprintf(vname, sizeof(vname), "cache_v%d", i);
927	                ex.input(kname, ctx->kv_cache[i].first);
928	                ex.input(vname, ctx->kv_cache[i].second);
929	            }
930	
931	            for (int i = 0; i < sconv_cnt; ++i) {
932	                char name[16];
933	                std::snprintf(name, sizeof(name), "cache_conv%d", i);
934	                ex.input(name, qwen_ctx->sconv_cache[i]);
935	            }
936	            for (int i = 0; i < gdr_cnt; ++i) {
