939	                ex.input(name, qwen_ctx->gdr_cache[i]);
940	            }
941	
942	            for (int i = 0; i < attn_cnt; ++i) {
943	                char kname[32], vname[32];
944	                std::snprintf(kname, sizeof(kname), "out_cache_k%d", i);
945	                std::snprintf(vname, sizeof(vname), "out_cache_v%d", i);
946	                ncnn::Mat k_cache, v_cache;
