953	                char name[32];
954	                std::snprintf(name, sizeof(name), "out_cache_conv%d", i);
955	                ncnn::Mat cache;
956	                ex.extract(name, cache);
957	                qwen_ctx->sconv_cache[i] = std::move(cache);
958	            }
