965	            }
966	
967	            ex.extract("out0", decode_out);
968	        }
969	
970	        ncnn::Mat logits_mat = llm_run_lm_head(*proj_out_net, decode_out);
971	
972	        LlmTokenSampleConfig sample_cfg;
973	        sample_cfg.vocab_size = vocab_size;
974	        sample_cfg.temperature = cfg.temperature;
975	        sample_cfg.top_p = cfg.top_p;
976	        sample_cfg.top_k = cfg.top_k;
