1020	ncnn::Mat ncnn_llm_gpt::bgr_to_pixel_values(const ncnn::Mat& bgr) const {
1021	    float image_mean[3] = {0.48145466f, 0.4578275f, 0.40821073f};
1022	    float image_std[3] = {0.26862954f, 0.26130258f, 0.27577711f};
1023	
1024	    if (vision_type == Vision_Type::VISION_QWEN3_5_VL) {
1025	        image_mean[0] = 0.5f; image_mean[1] = 0.5f; image_mean[2] = 0.5f;
1026	        image_std[0] = 0.5f; image_std[1] = 0.5f; image_std[2] = 0.5f;
1027	    }
1028	
1029	    int img_h = bgr.h;
1030	    int img_w = bgr.w;
1031	
1032	    int num_patches_h = (img_h + patch_size - 1) / patch_size;
1033	    int num_patches_w = (img_w + patch_size - 1) / patch_size;
1034	    int num_patches = num_patches_h * num_patches_w;
1035	
1036	    int embed_dim = patch_size * patch_size * 3;
1037	    ncnn::Mat pixel_values(embed_dim, num_patches);
1038	
1039	    const unsigned char* bgr_data = (const unsigned char*)bgr.data;
1040	
1041	    for (int p = 0; p < num_patches; p++) {
1042	        int ph = p / num_patches_w;
1043	        int pw = p % num_patches_w;
1044	        int start_y = ph * patch_size;
1045	        int start_x = pw * patch_size;
1046	
1047	        float* out_ptr = pixel_values.row(p);
1048	        float* ptr_r = out_ptr;
1049	        float* ptr_g = out_ptr + patch_size * patch_size;
1050	        float* ptr_b = out_ptr + patch_size * patch_size * 2;
1051	
1052	        for (int y = 0; y < patch_size; y++) {
1053	            const unsigned char* img_row_ptr = NULL;
1054	            int cur_img_y = start_y + y;
1055	            if (cur_img_y < img_h) {
1056	                img_row_ptr = bgr_data + cur_img_y * img_w * 3;
1057	            }
1058	
1059	            for (int x = 0; x < patch_size; x++) {
1060	                int cur_img_x = start_x + x;
1061	                if (img_row_ptr && cur_img_x < img_w) {
1062	                    const unsigned char* pixel = img_row_ptr + cur_img_x * 3;
1063	                    if (vision_type == Vision_Type::VISION_QWEN3_5_VL) {
1064	                        *ptr_r++ = (pixel[2] / 255.5f - image_mean[0]) / image_std[0];
1065	                        *ptr_g++ = (pixel[1] / 255.5f - image_mean[1]) / image_std[1];
1066	                        *ptr_b++ = (pixel[0] / 255.5f - image_mean[2]) / image_std[2];
1067	                    } else {
1068	                        *ptr_r++ = (pixel[2] / 255.f - image_mean[0]) / image_std[0];
1069	                        *ptr_g++ = (pixel[1] / 255.f - image_mean[1]) / image_std[1];
1070	                        *ptr_b++ = (pixel[0] / 255.f - image_mean[2]) / image_std[2];
1071	                    }
1072	                } else {
1073	                    float pad_val = 0.0f;
1074	                    *ptr_r++ = pad_val;
1075	                    *ptr_g++ = pad_val;
1076	                    *ptr_b++ = pad_val;
1077	                }
1078	            }
1079	        }
1080	    }
1081	    return pixel_values;
1082	}
