1115	void ncnn_llm_gpt::get_window_index(int num_patches_w, int num_patches_h, std::vector<int>& window_index, std::vector<int>& cu_window_seqlens) const {
1116	    const int vit_merger_window_size = 4;
1117	
1118	    int llm_grid_h = num_patches_h / spatial_merge_size;
1119	    int llm_grid_w = num_patches_w / spatial_merge_size;
1120	
1121	    int num_windows_h = (llm_grid_h + vit_merger_window_size - 1) / vit_merger_window_size;
1122	    int num_windows_w = (llm_grid_w + vit_merger_window_size - 1) / vit_merger_window_size;
1123	
1124	    window_index.clear();
1125	    window_index.reserve(llm_grid_h * llm_grid_w);
1126	
1127	    cu_window_seqlens.clear();
1128	    cu_window_seqlens.push_back(0);
1129	
1130	    int current_cu_len = 0;
1131	
1132	    for (int nh = 0; nh < num_windows_h; ++nh) {
1133	        for (int nw = 0; nw < num_windows_w; ++nw) {
1134	            int h_start = nh * vit_merger_window_size;
1135	            int w_start = nw * vit_merger_window_size;
1136	            int h_end = std::min(h_start + vit_merger_window_size, llm_grid_h);
1137	            int w_end = std::min(w_start + vit_merger_window_size, llm_grid_w);
1138	
1139	            int valid_h = h_end - h_start;
1140	            int valid_w = w_end - w_start;
1141	
1142	            if (valid_h <= 0 || valid_w <= 0) continue;
1143	
1144	            for (int r = h_start; r < h_end; ++r) {
1145	                for (int c = w_start; c < w_end; ++c) {
1146	                    int original_idx = r * llm_grid_w + c;
1147	                    window_index.push_back(original_idx);
1148	                }
1149	            }
1150	
1151	            int tokens_in_this_window = valid_h * valid_w * (spatial_merge_size * spatial_merge_size);
1152	            current_cu_len += tokens_in_this_window;
1153	            cu_window_seqlens.push_back(current_cu_len);
1154	        }
1155	    }
1156	}
